-- T0C-SYNC-1 (LD-322, LD-325; founder blanket authority LD-310; founder 2026-11-17 09:19 NPT offline requirement, 09:20 NPT own server in another office):
-- offline sync part 1 in schema core. Design source: C:/LIMS-state/offline-design-20261117.md (section 4 numbering, section 6 device registry).
-- New tenant tables (rows are never deleted: lims_app has SELECT, INSERT, UPDATE only and no DELETE policy; revoke and wipe keep the row for audit):
--   core.sync_device   one row per registered device (web PC, android, ios). The id is generated by the device (UUID) and is global
--                      (PRIMARY KEY (id)); registerSyncDevice is idempotent per id in the service. status active | revoked | wipe_requested,
--                      offline_retention_days default 14 (design section 6), last_clock_skew_ms = device minus server clock in ms.
--   core.number_block  a reserved range [from_value, to_value] (inclusive, integers from 1) of one series (lab_code | patient_id) for a device.
--                      Two blocks of one tenant and series never overlap, whatever the device or centre: BEFORE INSERT OR UPDATE trigger under a
--                      transaction advisory lock per tenant and series (btree_gist is not assumed present, so no EXCLUDE constraint).
--                      Unused numbers are recorded in skipped_count (a gap is allowed for these series). Bill, invoice and receipt numbers are
--                      never in blocks (provisional offline numbers, final gap free number at sync), so the series CHECK refuses them.
-- Widened core.g_permissions__code__ck: the code sync.use (named verbatim by LD-322) has two segments; the check now accepts 2 or 3 lowercase
-- segments (guarded DROP + ADD inside a DO block that reads pg_constraint, so a re-run changes nothing).
-- Additive only: new tables, function, triggers, policies, grants and the widened check; no data rewrite, no ENUM type, no sequence.
-- Idempotent: IF NOT EXISTS on tables and indexes, constraints inline, each CREATE POLICY guarded by pg_policy, function and triggers CREATE OR REPLACE.
-- Cloud apply is a founder step (push-cloud) after 20261117210000_partners__add_sales_hierarchy.sql; not done by this task.
-- DOWN (manual, never automatic; drops registered devices and reserved blocks: founder decision, export first):
--   DROP TABLE IF EXISTS core.number_block, core.sync_device CASCADE;
--   DROP FUNCTION IF EXISTS core.number_block__no_overlap();
--   g_permissions__code__ck back to three segments only after sync.use is removed from core.g_permissions (never while it is seeded).
SET LOCAL ROLE lims_owner;

-- ---------- (1) device registry ----------
CREATE TABLE IF NOT EXISTS core.sync_device (
  id                     uuid        NOT NULL,
  tenant_id              uuid        NOT NULL,
  user_id                uuid        NOT NULL,
  device_label           text        NOT NULL,
  platform               text        NOT NULL,
  app_version            text        NOT NULL,
  status                 text        NOT NULL DEFAULT 'active',
  first_seen_at          timestamptz NOT NULL DEFAULT now(),
  last_seen_at           timestamptz NOT NULL DEFAULT now(),
  last_sync_at           timestamptz,
  wipe_requested_at      timestamptz,
  wipe_acked_at          timestamptz,
  last_clock_skew_ms     bigint,
  offline_retention_days integer     NOT NULL DEFAULT 14,
  version                integer     NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT now(),
  created_by             uuid        NOT NULL,
  updated_at             timestamptz NOT NULL DEFAULT now(),
  updated_by             uuid        NOT NULL,
  CONSTRAINT sync_device__pk PRIMARY KEY (id),
  CONSTRAINT sync_device__tenant_id_id__uq UNIQUE (tenant_id, id),
  CONSTRAINT sync_device__tenant__fk FOREIGN KEY (tenant_id) REFERENCES core.tenants (id),
  CONSTRAINT sync_device__user__fk FOREIGN KEY (tenant_id, user_id) REFERENCES core.users (tenant_id, id),
  CONSTRAINT sync_device__platform__ck CHECK (platform IN ('web','android','ios')),
  CONSTRAINT sync_device__status__ck CHECK (status IN ('active','revoked','wipe_requested')),
  CONSTRAINT sync_device__device_label__ck CHECK (char_length(device_label) BETWEEN 1 AND 120),
  CONSTRAINT sync_device__app_version__ck CHECK (char_length(app_version) BETWEEN 1 AND 40),
  CONSTRAINT sync_device__offline_retention_days__ck CHECK (offline_retention_days BETWEEN 1 AND 365)
);
CREATE INDEX IF NOT EXISTS sync_device__tenant_id_user_id__idx ON core.sync_device (tenant_id, user_id);
CREATE INDEX IF NOT EXISTS sync_device__tenant_id_status__idx ON core.sync_device (tenant_id, status);

-- ---------- (2) number blocks (lab codes and patient ids only) ----------
CREATE TABLE IF NOT EXISTS core.number_block (
  id            uuid        NOT NULL,
  tenant_id     uuid        NOT NULL,
  device_id     uuid        NOT NULL,
  series        text        NOT NULL,
  centre_id     uuid,
  from_value    bigint      NOT NULL,
  to_value      bigint      NOT NULL,
  issued_at     timestamptz NOT NULL DEFAULT now(),
  exhausted_at  timestamptz,
  skipped_count bigint      NOT NULL DEFAULT 0,
  version       integer     NOT NULL DEFAULT 1,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid        NOT NULL,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid        NOT NULL,
  CONSTRAINT number_block__pk PRIMARY KEY (id),
  CONSTRAINT number_block__tenant_id_id__uq UNIQUE (tenant_id, id),
  CONSTRAINT number_block__tenant__fk FOREIGN KEY (tenant_id) REFERENCES core.tenants (id),
  CONSTRAINT number_block__device__fk FOREIGN KEY (tenant_id, device_id) REFERENCES core.sync_device (tenant_id, id),
  CONSTRAINT number_block__centre__fk FOREIGN KEY (tenant_id, centre_id) REFERENCES core.collection_centres (tenant_id, id),
  CONSTRAINT number_block__series__ck CHECK (series IN ('lab_code','patient_id')),
  CONSTRAINT number_block__range__ck CHECK (from_value >= 1 AND to_value >= from_value),
  CONSTRAINT number_block__skipped_count__ck CHECK (skipped_count >= 0)
);
CREATE INDEX IF NOT EXISTS number_block__tenant_id_series_from_value__idx ON core.number_block (tenant_id, series, from_value);
CREATE INDEX IF NOT EXISTS number_block__tenant_id_device_id__idx ON core.number_block (tenant_id, device_id);

-- two blocks of one tenant and series never overlap (inclusive bounds; centre and device do not matter). One reservation at a time per
-- tenant and series, so two concurrent reservations cannot both pass the check.
CREATE OR REPLACE FUNCTION core.number_block__no_overlap() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.from_value = OLD.from_value AND NEW.to_value = OLD.to_value AND NEW.series = OLD.series
     AND NEW.tenant_id = OLD.tenant_id THEN
    RETURN NEW;
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('core.number_block:' || NEW.tenant_id::text || ':' || NEW.series, 0));
  IF EXISTS (SELECT 1 FROM core.number_block b
              WHERE b.tenant_id = NEW.tenant_id AND b.series = NEW.series AND b.id <> NEW.id
                AND b.from_value <= NEW.to_value AND NEW.from_value <= b.to_value) THEN
    RAISE EXCEPTION USING ERRCODE = '23P01', MESSAGE = 'number_block_overlap', DETAIL = NEW.series;
  END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER number_block__no_overlap BEFORE INSERT OR UPDATE ON core.number_block
  FOR EACH ROW EXECUTE FUNCTION core.number_block__no_overlap();

-- ---------- (3) RLS by tenant (staff and system actors), policies, grants (no DELETE), audit ----------
ALTER TABLE core.sync_device ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.sync_device FORCE ROW LEVEL SECURITY;
ALTER TABLE core.number_block ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.number_block FORCE ROW LEVEL SECURITY;

DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.sync_device'::regclass AND polname = 'sync_device__select__tenant') THEN
  CREATE POLICY sync_device__select__tenant ON core.sync_device FOR SELECT TO lims_app
    USING (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.sync_device'::regclass AND polname = 'sync_device__insert__tenant') THEN
  CREATE POLICY sync_device__insert__tenant ON core.sync_device FOR INSERT TO lims_app
    WITH CHECK (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.sync_device'::regclass AND polname = 'sync_device__update__tenant') THEN
  CREATE POLICY sync_device__update__tenant ON core.sync_device FOR UPDATE TO lims_app
    USING (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()))
    WITH CHECK (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;

DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.number_block'::regclass AND polname = 'number_block__select__tenant') THEN
  CREATE POLICY number_block__select__tenant ON core.number_block FOR SELECT TO lims_app
    USING (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.number_block'::regclass AND polname = 'number_block__insert__tenant') THEN
  CREATE POLICY number_block__insert__tenant ON core.number_block FOR INSERT TO lims_app
    WITH CHECK (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'core.number_block'::regclass AND polname = 'number_block__update__tenant') THEN
  CREATE POLICY number_block__update__tenant ON core.number_block FOR UPDATE TO lims_app
    USING (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()))
    WITH CHECK (tenant_id = (SELECT app.current_tenant_id()) AND (SELECT app.is_staff_or_system()));
END IF; END $do$;

GRANT SELECT, INSERT, UPDATE ON core.sync_device TO lims_app;
GRANT SELECT, INSERT, UPDATE ON core.number_block TO lims_app;

CREATE OR REPLACE TRIGGER sync_device__audit AFTER INSERT OR UPDATE OR DELETE ON core.sync_device FOR EACH ROW EXECUTE FUNCTION app.tg_row_audit();
CREATE OR REPLACE TRIGGER number_block__audit AFTER INSERT OR UPDATE OR DELETE ON core.number_block FOR EACH ROW EXECUTE FUNCTION app.tg_row_audit();

-- ---------- (4) g_permissions__code__ck: 2 or 3 segments (sync.use) ----------
DO $do$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'core.g_permissions'::regclass AND conname = 'g_permissions__code__ck'
                    AND pg_get_constraintdef(oid) LIKE '%)?$%') THEN
    ALTER TABLE core.g_permissions DROP CONSTRAINT IF EXISTS g_permissions__code__ck;
    ALTER TABLE core.g_permissions ADD CONSTRAINT g_permissions__code__ck CHECK (code ~ '^[a-z_]+\.[a-z_]+(\.[a-z_]+)?$');
  END IF;
END $do$;
